-- 0001_core_schema.sql — PostgreSQL system of record (Hetzner).
-- DRAFT FOR PHASE 2. Not executed in Phase 1. Review with the API design
-- before applying. Mirrors MASTER_PLAN §8 and src/domain/*.
--
-- Conventions
-- * IDs are prefixed ULIDs generated by the API (src/domain/ids.ts), stored as text.
-- * Every tenant-owned table carries organisation_id and is protected by
--   row-level security keyed on the `app.organisation_id` setting, which the
--   API sets per transaction after authorising the request. The API's
--   database role is NOT a superuser and does not bypass RLS.
-- * Money is bigint minor units + ISO-4217 currency. Never numeric/float.
-- * Audit events are append-only.

begin;

create extension if not exists citext;

-- ── Tenancy and identity ────────────────────────────────────────────────

create table organisations (
  id               text primary key,
  kind             text not null check (kind in ('operator', 'partner')),
  name             text not null,
  legal_name       text,
  country_code     char(2),
  theme            jsonb not null default '{}'::jsonb,       -- TenantTheme tokens
  created_at       timestamptz not null default now()
);

create table users (
  id               text primary key,
  email            citext not null unique,
  display_name     text not null,
  password_hash    text,                                     -- null when using managed identity
  mfa_enrolled     boolean not null default false,
  disabled_at      timestamptz,
  created_at       timestamptz not null default now()
);

create table memberships (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  user_id          text not null references users(id),
  role             text not null check (role in ('platform_owner','company_admin','operations_manager','finance_operator','talent_manager','artist','client','partner_operator','auditor')),
  artist_id        text,                                     -- set for role = artist
  client_id        text,                                     -- set for role = client
  created_at       timestamptz not null default now(),
  revoked_at       timestamptz,
  unique (organisation_id, user_id, role)
);

create table sessions (
  id_hash          text primary key,                         -- SHA-256 of the opaque session token
  user_id          text not null references users(id),
  mfa_verified_at  timestamptz,
  expires_at       timestamptz not null,
  created_at       timestamptz not null default now(),
  user_agent       text
);

-- ── Creatives ───────────────────────────────────────────────────────────

create table artists (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  legal_name       text not null,
  stage_name       text,
  slug             text not null,
  verification     text not null default 'unverified' check (verification in ('unverified','in-review','verified','suspended')),
  public_listing_approved_at timestamptz,                    -- written approval to be listed publicly
  approval_reference text,
  theme            jsonb not null default '{}'::jsonb,
  created_at       timestamptz not null default now(),
  unique (organisation_id, slug)
);

create table artist_profiles (
  artist_id        text primary key references artists(id),
  organisation_id  text not null references organisations(id),
  headline         text,
  bio              text,
  city             text,
  country_code     char(2),
  languages        text[] not null default '{}',
  roles            text[] not null default '{}',
  genres           text[] not null default '{}',
  working_modes    text[] not null default '{}',
  remote_ready     boolean not null default false,
  updated_at       timestamptz not null default now()
);

create table media_assets (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  artist_id        text references artists(id),
  kind             text not null check (kind in ('image','audio','video','document')),
  r2_key           text not null,                            -- private bucket key
  width            int,
  height           int,
  duration_ms      int,
  approved_for_public_at timestamptz,                        -- artist approval before public delivery
  virus_scan       text not null default 'pending' check (virus_scan in ('pending','clean','infected','failed')),
  created_at       timestamptz not null default now()
);

create table credits (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  artist_id        text not null references artists(id),
  release_title    text not null,
  role             text not null,
  verified_at      timestamptz,
  verified_with    text                                      -- release owner contact or evidence reference
);

create table availability (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  artist_id        text not null references artists(id),
  starts_on        date not null,
  ends_on          date not null,
  status           text not null check (status in ('available','limited','booked','away')),
  check (ends_on >= starts_on)
);

-- ── CRM, consent and enquiries ─────────────────────────────────────────

create table contacts (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  email_normalised citext not null,
  phone_e164       text,
  name             text not null,
  country          text,
  lawful_basis     text not null,
  sources          text[] not null default '{}',
  suppressed_at    timestamptz,                              -- unsubscribe / do-not-contact
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (organisation_id, email_normalised)
);

create table consent_records (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  contact_id       text not null references contacts(id),
  purpose          text not null check (purpose in ('privacy-notice','marketing')),
  granted          boolean not null,
  wording_version  text not null,
  source           text not null,
  recorded_at      timestamptz not null,
  withdrawn_at     timestamptz
);

create table clients (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  name             text not null,
  primary_contact_id text references contacts(id),
  created_at       timestamptz not null default now()
);

create table enquiries (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  reference        text not null,
  contact_id       text not null references contacts(id),
  state            text not null default 'new' check (state in ('new','triaged','scoping','quoted','won','lost','archived','spam')),
  payload          jsonb not null,                           -- validated EnquiryInput minus consent fields
  idempotency_key  text not null,
  created_at       timestamptz not null default now(),
  unique (organisation_id, idempotency_key)
);

create table applications (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  reference        text not null,
  contact_id       text not null references contacts(id),
  state            text not null default 'received' check (state in ('received','under-review','shortlisted','verification','verified','declined','withdrawn')),
  payload          jsonb not null,
  rights_confirmed_at timestamptz not null,
  idempotency_key  text not null,
  created_at       timestamptz not null default now(),
  unique (organisation_id, idempotency_key)
);

-- ── Opportunities and projects ─────────────────────────────────────────

create table opportunities (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  title            text not null,
  kind             text not null,
  roles            text[] not null default '{}',
  genres           text[] not null default '{}',
  remote           boolean not null default true,
  closes_at        timestamptz,
  status           text not null default 'draft' check (status in ('draft','open','shortlisting','filled','closed')),
  created_at       timestamptz not null default now()
);

create table matches (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  opportunity_id   text not null references opportunities(id),
  artist_id        text not null references artists(id),
  status           text not null check (status in ('suggested','applied','shortlisted','accepted','declined')),
  created_at       timestamptz not null default now(),
  unique (opportunity_id, artist_id)
);

create table projects (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  client_id        text not null references clients(id),
  enquiry_id       text references enquiries(id),
  title            text not null,
  status           text not null default 'scoping' check (status in ('scoping','contracting','in-progress','in-review','delivered','closed','disputed')),
  currency         char(3) not null,
  created_at       timestamptz not null default now()
);

create table project_participants (
  project_id       text not null references projects(id),
  organisation_id  text not null references organisations(id),
  artist_id        text not null references artists(id),
  role             text not null,
  fee_weight       numeric(9,4) not null check (fee_weight >= 0),
  primary key (project_id, artist_id)
);

create table milestones (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  title            text not null,
  due_on           date,
  revision_rounds  int not null default 2,
  status           text not null default 'pending' check (status in ('pending','in-progress','submitted','changes-requested','approved')),
  approved_at      timestamptz
);

create table tasks (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  milestone_id     text references milestones(id),
  assignee_user_id text references users(id),
  title            text not null,
  due_on           date,
  done_at          timestamptz
);

create table deliverables (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  milestone_id     text not null references milestones(id),
  media_asset_id   text not null references media_assets(id),
  version          int not null,
  submitted_by     text not null references users(id),
  status           text not null default 'submitted' check (status in ('submitted','qa-passed','qa-failed','client-approved','changes-requested')),
  created_at       timestamptz not null default now(),
  unique (milestone_id, media_asset_id, version)
);

create table comments (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  entity           text not null,
  entity_id        text not null,
  author_user_id   text not null references users(id),
  body             text not null,
  created_at       timestamptz not null default now()
);

-- ── Contracts, rights and money ────────────────────────────────────────

create table contracts (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text references projects(id),
  kind             text not null check (kind in ('client-services','creative-engagement','licence','partner')),
  status           text not null default 'draft' check (status in ('draft','sent','signed','void')),
  commission       jsonb,                                    -- CommissionModel, per contract (src/domain/settlement.ts)
  created_at       timestamptz not null default now()
);

create table contract_versions (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  contract_id      text not null references contracts(id),
  version          int not null,
  document_r2_key  text not null,
  sha256           text not null,
  created_at       timestamptz not null default now(),
  unique (contract_id, version)
);

create table signatures (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  contract_version_id text not null references contract_versions(id),
  signer_user_id   text not null references users(id),
  signed_at        timestamptz not null,
  method           text not null,
  evidence         jsonb not null default '{}'::jsonb
);

create table split_sheets (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  work_title       text not null,
  right_type       text not null check (right_type in ('composition','master')),
  status           text not null default 'draft' check (status in ('draft','circulating','signed'))
);

create table split_shares (
  split_sheet_id   text not null references split_sheets(id),
  organisation_id  text not null references organisations(id),
  party            text not null,
  artist_id        text references artists(id),
  bps              int not null check (bps > 0 and bps <= 10000),
  primary key (split_sheet_id, party)
);

create table quotes (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  status           text not null default 'draft' check (status in ('draft','sent','accepted','superseded','declined'))
);

create table quote_versions (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  quote_id         text not null references quotes(id),
  version          int not null,
  scope            jsonb not null,
  total_minor      bigint not null check (total_minor >= 0),
  currency         char(3) not null,
  created_at       timestamptz not null default now(),
  unique (quote_id, version)
);

create table invoices (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  number           text not null,                            -- issued only by the contracting legal entity
  status           text not null default 'draft' check (status in ('draft','issued','part-paid','paid','void')),
  currency         char(3) not null,
  issued_at        timestamptz,
  due_at           timestamptz,
  unique (organisation_id, number)
);

create table invoice_lines (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  invoice_id       text not null references invoices(id),
  description      text not null,
  amount_minor     bigint not null,
  tax_minor        bigint not null default 0
);

create table payments (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  invoice_id       text not null references invoices(id),
  provider         text not null,
  provider_transaction_id text not null,
  amount_minor     bigint not null,
  currency         char(3) not null,
  fee_minor        bigint not null default 0,
  fx_rate          numeric(18,8),
  reconciliation   text not null default 'unreconciled' check (reconciliation in ('unreconciled','matched','disputed')),
  received_at      timestamptz not null,
  unique (provider, provider_transaction_id)
);

create table refunds (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  payment_id       text not null references payments(id),
  amount_minor     bigint not null check (amount_minor > 0),
  reason           text not null,
  refunded_at      timestamptz not null
);

create table expenses (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  description      text not null,
  amount_minor     bigint not null check (amount_minor >= 0),
  currency         char(3) not null,
  approved_by      text references users(id),
  approved_at      timestamptz,
  receipt_r2_key   text
);

create table commissions (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  contract_id      text not null references contracts(id),
  amount_minor     bigint not null check (amount_minor >= 0),
  currency         char(3) not null,
  calculated_at    timestamptz not null default now()
);

create table payout_statements (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  project_id       text not null references projects(id),
  artist_id        text not null references artists(id),
  gross_receipts_minor bigint not null,
  approved_costs_minor bigint not null,
  commission_minor bigint not null,
  share_minor      bigint not null,
  currency         char(3) not null,
  status           text not null default 'draft' check (status in ('draft','issued','paid')),
  issued_at        timestamptz
);

create table payouts (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  payout_statement_id text not null references payout_statements(id),
  amount_minor     bigint not null,
  currency         char(3) not null,
  method           text not null,
  reference        text,
  paid_at          timestamptz,
  approved_by      text references users(id)                -- requires finance role + MFA (src/domain/permissions.ts)
);

-- ── Documents, websites, analytics ─────────────────────────────────────

create table documents (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  owner_entity     text not null,
  owner_id         text not null,
  kind             text not null,
  r2_key           text not null,
  sensitivity      text not null default 'standard' check (sensitivity in ('standard','finance','identity')),
  created_at       timestamptz not null default now()
);

create table website_projects (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  artist_id        text references artists(id),
  client_id        text references clients(id),
  domain           text,
  status           text not null default 'planning' check (status in ('planning','design','build','live','paused')),
  hosting_plan     text
);

create table analytics_daily (
  organisation_id  text not null references organisations(id),
  day              date not null,
  path             text not null,
  event            text not null,
  count            int not null,
  primary key (organisation_id, day, path, event)
);

-- ── Partners and support (status only — never case detail) ────────────

create table partner_referrals (
  id               text primary key,
  organisation_id  text not null references organisations(id),   -- operator tenant that owns the artist record
  partner_organisation_id text not null references organisations(id),
  artist_id        text not null references artists(id),
  programme        text,
  status           text not null check (status in ('referred','enrolled','active','completed','withdrawn')),
  created_at       timestamptz not null default now()
);

create table partner_consents (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  partner_organisation_id text not null references organisations(id),
  artist_id        text not null references artists(id),
  scope            text[] not null,                                 -- e.g. {'referral-status','impact-aggregates'}
  granted_at       timestamptz not null,
  withdrawn_at     timestamptz
);

create table support_cases (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  partner_organisation_id text not null references organisations(id),
  artist_id        text not null references artists(id),
  category         text not null check (category in ('legal','wellness','financial','business','other')),
  status           text not null check (status in ('requested','acknowledged','in-progress','closed')),
  updated_at       timestamptz not null default now()
  -- Deliberately no free-text detail column: sensitive detail stays with the
  -- regulated provider, never in this database (MASTER_PLAN §4).
);

create table tags (
  organisation_id  text not null references organisations(id),
  entity           text not null,
  entity_id        text not null,
  tag              text not null,
  primary key (organisation_id, entity, entity_id, tag)
);

create table audit_events (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  actor_user_id    text references users(id),
  actor_kind       text not null check (actor_kind in ('user','public-form','system','worker')),
  action           text not null,
  entity           text not null,
  entity_id        text not null,
  detail           jsonb not null default '{}'::jsonb,
  at               timestamptz not null default now()
);

create table outbox (
  id               text primary key,
  organisation_id  text not null references organisations(id),
  channel          text not null check (channel in ('internal-alert','acknowledgement-email','email','webhook')),
  template         text not null,
  entity_id        text not null,
  status           text not null default 'queued' check (status in ('queued','sending','sent','failed','dead')),
  attempts         int not null default 0,
  last_error       text,
  created_at       timestamptz not null default now(),
  sent_at          timestamptz
);

-- ── Audit log is append-only ───────────────────────────────────────────

create function forbid_audit_mutation() returns trigger language plpgsql as $$
begin
  raise exception 'audit_events is append-only';
end $$;

create trigger audit_events_append_only before update or delete on audit_events
  for each row execute function forbid_audit_mutation();

-- ── Row-level security on every tenant-owned table ─────────────────────

do $$
declare t text;
begin
  for t in
    select table_name from information_schema.columns
    where table_schema = 'public' and column_name = 'organisation_id'
  loop
    execute format('alter table %I enable row level security', t);
    execute format('alter table %I force row level security', t);
    execute format(
      'create policy tenant_isolation on %I using (organisation_id = current_setting(''app.organisation_id'', true)) with check (organisation_id = current_setting(''app.organisation_id'', true))',
      t);
  end loop;
end $$;

-- Sign-in must list a user's memberships across tenants before a tenant is
-- chosen. That lookup runs as a separate, narrowly granted auth role through a
-- SECURITY DEFINER function returning (organisation_id, role) only; the
-- general API role never bypasses RLS.
--
-- Partner operators read referrals and support status through views that
-- join partner_consents; they never receive a session scoped to an operator
-- tenant. Those views are defined with the Phase 2 API.

commit;
